const event = (year, title, description, keys, category = 'politics', placeKey) => ({ year, title, description, sourceIds: ids(keys), category, ...(placeKey ? { placeId: P[placeKey].id } : {}) });
const scene = (id, year, title, kicker, summary, places, sections, events, figureKeys, polityKeys, tags, note = '') => {
  const era = year <= 313 ? 'early' : year <= 697 ? 'three' : year <= 899 ? 'northsouth' : 'later';
  const color = polities.find(p => p.id === `anc-${polityKeys[0]}`)?.color || C.event;
  return { id, year, era, title, kicker, summary, color, note: note || '도시·유적의 대표 위치를 표시한다. 지도점과 색은 당시의 국경이나 정밀한 전장을 뜻하지 않는다.', places, sections, events, figureIds: ids(figureKeys), polityIds: ids(polityKeys), tags, sourceIds: unique([...places.flatMap(p => p.sourceIds), ...sections.flatMap(s => s.sourceIds), ...events.flatMap(e => e.sourceIds)]) };
};

